# meiva:note
# Generates ui/web/src/lib/contracts/constants-generated.ts from the backend owners of facts the
# frontend also needs: EVENT_COALESCE_MS (base/events/live/projection.py), the user-reply header
# (base/agents/messages/reply_intent.py) and the NoteTag value set (base/agents/messages/kwargs.py).
# The frontend imports the generated file, so the two sides cannot drift apart. Run it after
# changing a source, or let pre-commit's `constants-codegen-fresh` hook fail on drift.
# meiva:link base/agents/messages/docs/metadata-contracts.meiva.okf.md

from __future__ import annotations

import json
import sys
from pathlib import Path

# Put project root on sys.path so `from base.events.live.projection import ...` finds
# this checkout's module (without it, an editable install of another checkout
# shadows it — same pattern as dump_event_fixtures.py / dump_openapi.py).
sys.path.insert(0, str(Path(__file__).resolve().parent.parent.parent))
from base.host.env.boot_actions import enter_scratch_home

if __name__ == "__main__":
    enter_scratch_home()


from base.agents.messages.kwargs import NoteTag
from base.agents.messages.reply_intent import (
    DISPLAY_TO_USER,
    HIDE_FROM_USER,
    USER_REPLY_HEADER,
    USER_REPLY_PREFIX,
)
from base.events.live.projection import EVENT_COALESCE_MS

_OUT = Path("ui/web/src/lib/contracts/constants-generated.ts")

_HEADER = """// meiva:note
// Auto-generated by scripts/codegen/dump_frontend_constants.py — do not edit directly.
// SSE_EVENT_WINDOW_MS keeps the frontend stream re-parse throttle aligned with the backend
// event publisher coalesce window (~25 FPS).
// meiva:link base/events/live/projection.py
export const SSE_EVENT_WINDOW_MS = {coalesce_ms};

// meiva:link base/agents/messages/reply_intent.py
export const USER_REPLY_HEADER = {user_reply_header};
// meiva:link base/agents/messages/reply_intent.py
export const USER_REPLY_PREFIX = {user_reply_prefix};
export const DISPLAY_TO_USER = {display_to_user};
export const HIDE_FROM_USER = {hide_from_user};

// meiva:link base/agents/messages/kwargs.py
export const NOTE_TAGS = [
{note_tags}
] as const;
"""


def main(out_dir: str | None = None) -> None:
    out = Path(out_dir) / "constants-generated.ts" if out_dir else _OUT
    out.write_text(
        _HEADER.format(
            coalesce_ms=EVENT_COALESCE_MS,
            user_reply_header=json.dumps(USER_REPLY_HEADER),
            user_reply_prefix=json.dumps(USER_REPLY_PREFIX),
            display_to_user=json.dumps(DISPLAY_TO_USER),
            hide_from_user=json.dumps(HIDE_FROM_USER),
            note_tags="\n".join(f"  {json.dumps(tag.value)}," for tag in NoteTag),
        )
    )
    if not out_dir:
        print(f"wrote {out} (SSE_EVENT_WINDOW_MS = {EVENT_COALESCE_MS} ms)")


if __name__ == "__main__":
    sys.exit(main(sys.argv[1] if len(sys.argv) > 1 else None))
